package dev.jackteng.encore;
import dev.jackteng.encore.catalog.*;
import dev.jackteng.encore.catalog.Models.*;
import dev.jackteng.encore.customer.CustomerService;
import dev.jackteng.encore.customer.CustomerService.Principal;
import dev.jackteng.encore.orders.*;
import dev.jackteng.encore.orders.OrderModels.*;
import dev.jackteng.encore.orders.OrderModels.Order;
import dev.jackteng.encore.common.ApiErrors.Problem;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.test.web.servlet.MockMvc;
import jakarta.servlet.http.Cookie;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"ticket.delivery.enabled=false","ticket.orders.enabled=true","ticket.admission.enabled=false","ticket.expiry.enabled=false","ticket.mock-payments.enabled=false"})
@AutoConfigureMockMvc
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class OrderIntegrationTest {
 @Autowired OrderService orders;@Autowired CatalogService catalog;@Autowired CustomerService customers;
 @Autowired JdbcTemplate db;@Autowired ObjectMapper json;@Autowired PlatformTransactionManager transactions;@Autowired MockMvc mvc;
 String manager="orders-manager-"+UUID.randomUUID();
 record Fixture(Event event,Session session,Ticket ticket) {}
 @BeforeAll void seed(){assertEquals("ticket_demo",db.queryForObject("SELECT current_database()",String.class));db.update("INSERT INTO staff_account VALUES(?,?,?,?,true)",UUID.randomUUID(),manager,"unused synthetic hash","MANAGER");}
 Principal customer(){var issued=customers.register("o-"+UUID.randomUUID().toString().substring(0,30),"合成顧客",UUID.randomUUID().toString());return customers.authenticate(issued.token()).orElseThrow();}
 Fixture fixture(int capacity,int limit){return fixture(capacity,limit,OffsetDateTime.now().minusMinutes(1),OffsetDateTime.now().plusHours(1),true);}
 Fixture fixture(int capacity,int limit,OffsetDateTime start,OffsetDateTime end,boolean publish){
  var e=catalog.createEvent(manager,new EventInput(UUID.randomUUID(),0L,"orders-"+UUID.randomUUID(),"保票合成活動","合成資料","合成場地"));
  var s=catalog.createSession(manager,e.id(),new SessionInput(UUID.randomUUID(),0L,"合成晚場",end.plusDays(1),start,end));
  var t=catalog.createTicket(manager,s.id(),new TicketInput(UUID.randomUUID(),0L,"一般票",1200,capacity,limit));
  if(publish)e=catalog.transition(manager,e.id(),new Transition(UUID.randomUUID(),1L),true);
  return new Fixture(e,s,t);
 }
 Place place(Fixture f,int q){return new Place(UUID.randomUUID(),f.ticket().id(),q,1,1200*q);}
 void problem(int status,Runnable op){assertEquals(status,assertThrows(Problem.class,op::run).status);}
 int held(Fixture f){return db.queryForObject("SELECT held FROM ticket_type WHERE id=?",Integer.class,f.ticket().id());}
 void due(Order o){db.update("WITH stamp AS MATERIALIZED(SELECT clock_timestamp() AS clock) UPDATE ticket_order SET created_at=clock-interval '11 minutes',expires_at=clock-interval '1 minute' FROM stamp WHERE id=?",o.id());}
 long releases(Order o){return db.queryForObject("SELECT count(*) FROM order_inventory_event WHERE order_id=? AND phase='RELEASE'",Long.class,o.id());}
 void awaitTicketWait(){for(int i=0;i<50;i++){db.execute("SELECT pg_stat_clear_snapshot()");if(db.queryForObject("SELECT count(*) FROM pg_stat_activity WHERE datname=current_database() AND wait_event_type='Lock' AND query LIKE '%FOR UPDATE OF t%'",Integer.class)>0)return;try{Thread.sleep(30);}catch(InterruptedException e){throw new AssertionError(e);}}fail("Request must actually wait on ticket lock");}
 @Test void holdSnapshotAndBoundedDeadline(){var f=fixture(10,4);var c=customer();var o=orders.place(c,place(f,2));assertEquals("PENDING_PAYMENT",o.status());assertEquals(2400,o.totalTwd());assertEquals(2,held(f));assertEquals(Duration.ofMinutes(10),Duration.between(o.createdAt(),o.expiresAt()));assertEquals(8,catalog.detail(f.event().id(),true).sessions().getFirst().tickets().getFirst().available());}
 @Test void deadlineNeverExceedsSalesEnd(){var end=OffsetDateTime.now().plusSeconds(40);var f=fixture(2,2,OffsetDateTime.now().minusMinutes(1),end,true);var o=orders.place(customer(),place(f,1));assertEquals(f.session().salesEnd().toInstant(),o.expiresAt().toInstant());}
 @Test void quoteMismatchDoesNotHold(){var f=fixture(2,2);var c=customer();problem(409,()->orders.place(c,new Place(UUID.randomUUID(),f.ticket().id(),1,2,1200)));problem(409,()->orders.place(c,new Place(UUID.randomUUID(),f.ticket().id(),1,1,1)));assertEquals(0,held(f));}
 @Test void draftUpcomingClosedAndArchiveCannotPlace(){var now=OffsetDateTime.now();var c=customer();for(var f:List.of(fixture(1,1,now.minusMinutes(1),now.plusHours(1),false),fixture(1,1,now.plusHours(1),now.plusHours(2),true),fixture(1,1,now.minusHours(2),now.minusHours(1),false))){problem(409,()->orders.place(c,place(f,1)));assertEquals(0,held(f));}var f=fixture(1,1);catalog.transition(manager,f.event().id(),new Transition(UUID.randomUUID(),2L),false);problem(409,()->orders.place(c,place(f,1)));}
 @Test void sameBodyReplayAndChangedBodyConflict(){var f=fixture(5,5);var c=customer();var body=place(f,1);var o=orders.place(c,body);assertEquals(o,orders.place(c,body));problem(409,()->orders.place(c,new Place(body.requestId(),body.ticketId(),2,1,2400)));assertEquals(1,held(f));}
 @Test void concurrentReplayOnlyOneHold()throws Exception {var f=fixture(6,6);var c=customer();var body=place(f,1);try(var pool=Executors.newFixedThreadPool(6)){var calls=new ArrayList<Callable<Order>>();for(int i=0;i<6;i++)calls.add(()->orders.place(c,body));var r=pool.invokeAll(calls);UUID id=r.getFirst().get().id();for(var x:r)assertEquals(id,x.get().id());}assertEquals(1,held(f));}
 @Test void lastTicketOnlyOneCustomerWins()throws Exception {var f=fixture(1,1);var calls=new ArrayList<Callable<Boolean>>();for(int i=0;i<6;i++){var c=customer();calls.add(()->{try{orders.place(c,place(f,1));return true;}catch(Problem p){assertEquals("SOLD_OUT",p.code);return false;}});}try(var pool=Executors.newFixedThreadPool(6)){int won=0;for(var r:pool.invokeAll(calls))if(r.get())won++;assertEquals(1,won);}assertEquals(1,held(f));}
 @Test void concurrentSameCustomerLimitAcrossOrders()throws Exception {var f=fixture(10,3);var c=customer();Callable<Boolean> call=()->{try{orders.place(c,place(f,2));return true;}catch(Problem p){assertEquals("PURCHASE_LIMIT",p.code);return false;}};try(var pool=Executors.newFixedThreadPool(2)){var r=pool.invokeAll(List.of(call,call));assertNotEquals(r.get(0).get(),r.get(1).get());}assertEquals(2,held(f));}
 @Test void requestIdsScopedByOwner(){var f=fixture(5,5);var body=place(f,1);var a=orders.place(customer(),body);var b=orders.place(customer(),body);assertNotEquals(a.id(),b.id());assertEquals(2,held(f));}
 @Test void maximumFivePendingOrders(){var f=fixture(10,10,OffsetDateTime.now().minusMinutes(1),OffsetDateTime.now().plusHours(1),false);var tickets=new ArrayList<Ticket>();tickets.add(f.ticket());for(int i=0;i<5;i++)tickets.add(catalog.createTicket(manager,f.session().id(),new TicketInput(UUID.randomUUID(),0L,"票種"+i,1200,10,10)));catalog.transition(manager,f.event().id(),new Transition(UUID.randomUUID(),1L),true);var c=customer();Order first=null;for(int i=0;i<5;i++){var o=orders.place(c,new Place(UUID.randomUUID(),tickets.get(i).id(),1,1,1200));if(i==0)first=o;}problem(409,()->orders.place(c,new Place(UUID.randomUUID(),tickets.get(5).id(),1,1,1200)));orders.cancel(c,first.id(),new Cancel(UUID.randomUUID(),1));assertNotNull(orders.place(c,new Place(UUID.randomUUID(),tickets.get(5).id(),1,1,1200)));}
 @Test void cancellationReleasesOnceAndReplayNeverRevives(){var f=fixture(2,2);var c=customer();var body=place(f,1);var o=orders.place(c,body);var cancel=new Cancel(UUID.randomUUID(),1);var closed=orders.cancel(c,o.id(),cancel);assertEquals("CANCELLED",closed.status());assertEquals(2,closed.version());assertEquals(closed,orders.cancel(c,o.id(),cancel));assertEquals(closed,orders.place(c,body));assertEquals(0,held(f));assertEquals(1,releases(o));assertFalse(orders.expire(o.id()));}
 @Test void crossActionRequestReuseAndStaleCancelRejected(){var f=fixture(2,2);var c=customer();var body=place(f,1);var o=orders.place(c,body);problem(409,()->orders.cancel(c,o.id(),new Cancel(body.requestId(),1)));problem(409,()->orders.cancel(c,o.id(),new Cancel(UUID.randomUUID(),2)));assertEquals(1,held(f));}
 @Test void ownerIsolationAndPaging(){var f=fixture(2,2);var a=customer();var b=customer();var o=orders.place(a,place(f,1));problem(404,()->orders.detail(b,o.id()));problem(404,()->orders.cancel(b,o.id(),new Cancel(UUID.randomUUID(),1)));assertEquals(0,orders.list(b,1,10).total());problem(400,()->orders.list(a,1,21));}
 @Test void historyAndCancellationSurviveArchive(){var f=fixture(2,2);var c=customer();var o=orders.place(c,place(f,1));catalog.transition(manager,f.event().id(),new Transition(UUID.randomUUID(),2L),false);assertEquals(o.eventTitle(),orders.detail(c,o.id()).eventTitle());assertEquals("CANCELLED",orders.cancel(c,o.id(),new Cancel(UUID.randomUUID(),1)).status());}
 @Test void expiredHoldCountsUntilPhysicalRelease(){var f=fixture(1,1);var c=customer();var o=orders.place(c,place(f,1));due(o);problem(409,()->orders.place(c,place(f,1)));assertTrue(orders.expire(o.id()));assertFalse(orders.expire(o.id()));assertEquals("EXPIRED",orders.detail(c,o.id()).status());assertNotNull(orders.place(c,place(f,1)));assertEquals(1,releases(o));}
 @Test void dueCancellationUsesExpiredStatus(){var f=fixture(1,1);var c=customer();var o=orders.place(c,place(f,1));due(o);assertEquals("EXPIRED",orders.cancel(c,o.id(),new Cancel(UUID.randomUUID(),1)).status());assertEquals(0,held(f));}
 @Test void cancelCompetesWithMultipleExpiryWorkers()throws Exception {var f=fixture(2,2);var c=customer();var o=orders.place(c,place(f,1));due(o);try(var pool=Executors.newFixedThreadPool(4)){var calls=new ArrayList<Callable<Object>>();calls.add(()->{try{return orders.cancel(c,o.id(),new Cancel(UUID.randomUUID(),1));}catch(Problem p){assertEquals(409,p.status);return null;}});for(int i=0;i<3;i++)calls.add(()->orders.expire(o.id()));for(var r:pool.invokeAll(calls))r.get();}assertEquals(0,held(f));assertEquals(1,releases(o));assertEquals("EXPIRED",orders.detail(c,o.id()).status());}
 @Test void disabledCustomerCannotWriteButWorkerStillReleases(){var f=fixture(2,2);var c=customer();var o=orders.place(c,place(f,1));db.update("UPDATE customer_account SET enabled=false WHERE id=?",c.id());problem(401,()->orders.cancel(c,o.id(),new Cancel(UUID.randomUUID(),1)));due(o);assertTrue(orders.expire(o.id()));assertEquals(0,held(f));db.update("UPDATE customer_account SET enabled=true WHERE id=?",c.id());problem(401,()->orders.place(c,place(f,1)));}
 @Test void logoutRevokesWriteIdentity(){var f=fixture(2,2);var c=customer();db.update("DELETE FROM customer_session WHERE token_hash=?",c.sessionHash());problem(401,()->orders.place(c,place(f,1)));assertEquals(0,held(f));}
 @Test void holdAuditFailureRollsBackWholeCommand(){var f=fixture(2,2);var c=customer();var body=place(f,1);db.execute("ALTER TABLE order_inventory_event ADD CONSTRAINT m2b_hold_fault CHECK(ticket_id<>'"+f.ticket().id()+"'::uuid) NOT VALID");try{assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->orders.place(c,body));assertEquals(0,held(f));assertEquals(0,db.queryForObject("SELECT count(*) FROM ticket_order WHERE customer_id=?",Integer.class,c.id()));assertEquals(0,db.queryForObject("SELECT count(*) FROM order_command WHERE customer_id=?",Integer.class,c.id()));}finally{db.execute("ALTER TABLE order_inventory_event DROP CONSTRAINT m2b_hold_fault");}assertNotNull(orders.place(c,body));assertEquals(1,held(f));}
 @Test void releaseAuditFailureRollsBackAndOriginalCancelCanRetry(){var f=fixture(2,2);var c=customer();var o=orders.place(c,place(f,1));var cancel=new Cancel(UUID.randomUUID(),1);db.execute("ALTER TABLE order_inventory_event ADD CONSTRAINT m2b_release_fault CHECK(NOT(order_id='"+o.id()+"'::uuid AND phase='RELEASE')) NOT VALID");try{assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->orders.cancel(c,o.id(),cancel));assertEquals(1,held(f));assertEquals("PENDING_PAYMENT",orders.detail(c,o.id()).status());}finally{db.execute("ALTER TABLE order_inventory_event DROP CONSTRAINT m2b_release_fault");}assertEquals("CANCELLED",orders.cancel(c,o.id(),cancel).status());assertEquals(1,releases(o));}
 @Test void doesNotUseGlobalCatalogGuard()throws Exception {var f=fixture(2,2);var c=customer();try(var pool=Executors.newSingleThreadExecutor()){new TransactionTemplate(transactions).execute(s->{db.queryForObject("SELECT id FROM catalog_guard WHERE id=1 FOR UPDATE",Integer.class);try{assertNotNull(pool.submit(()->orders.place(c,place(f,1))).get(3,TimeUnit.SECONDS));}catch(Exception e){throw new AssertionError(e);}return null;});}}
 @Test void salesDeadlineCheckedAfterTicketLock()throws Exception {var c=customer();var f=fixture(2,2,OffsetDateTime.now().minusMinutes(1),OffsetDateTime.now().plusSeconds(4),true);try(var pool=Executors.newSingleThreadExecutor()){new TransactionTemplate(transactions).execute(s->{db.queryForObject("SELECT id FROM ticket_type WHERE id=? FOR UPDATE",UUID.class,f.ticket().id());var result=pool.submit(()->{problem(409,()->orders.place(c,place(f,1)));});awaitTicketWait();try{Thread.sleep(Math.max(1,Duration.between(OffsetDateTime.now(),f.session().salesEnd()).toMillis()+100));}catch(InterruptedException e){throw new AssertionError(e);}s.setRollbackOnly();return result;}).get(4,TimeUnit.SECONDS);}assertEquals(0,held(f));}
 @Test void authDeadlineCheckedAfterTicketLock()throws Exception {var f=fixture(2,2);var c=customer();db.update("UPDATE customer_session SET expires_at=clock_timestamp()+interval '3 seconds' WHERE token_hash=?",c.sessionHash());try(var pool=Executors.newSingleThreadExecutor()){new TransactionTemplate(transactions).execute(s->{db.queryForObject("SELECT id FROM ticket_type WHERE id=? FOR UPDATE",UUID.class,f.ticket().id());var result=pool.submit(()->{problem(401,()->orders.place(c,place(f,1)));});awaitTicketWait();try{Thread.sleep(3100);}catch(InterruptedException e){throw new AssertionError(e);}s.setRollbackOnly();return result;}).get(4,TimeUnit.SECONDS);}assertEquals(0,held(f));}
 @Test void disabledFeatureStillAllowsOriginalReplayAndRelease(){var f=fixture(2,2);var c=customer();var body=place(f,1);var o=orders.place(c,body);var off=new OrderService(db,json,false);var tx=new TransactionTemplate(transactions);assertEquals(o,tx.execute(s->off.place(c,body)));problem(409,()->tx.execute(s->off.place(c,place(f,1))));assertEquals("CANCELLED",tx.execute(s->off.cancel(c,o.id(),new Cancel(UUID.randomUUID(),1))).status());assertEquals(0,held(f));}
 @Test void inventoryConstraintsAndLegacySnapshot(){var f=fixture(2,2);var o=orders.place(customer(),place(f,2));assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->db.update("UPDATE ticket_type SET sold=1 WHERE id=?",f.ticket().id()));assertEquals(2,held(f));assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->db.update("INSERT INTO order_inventory_event SELECT * FROM order_inventory_event WHERE order_id=?",o.id()));assertDoesNotThrow(()->{var legacy=json.readValue("{\"id\":\""+f.ticket().id()+"\",\"name\":\"一般票\",\"priceTwd\":1200,\"capacity\":2,\"maxPerCustomer\":2,\"version\":1}",Ticket.class);assertEquals(2,legacy.available());});}
 @Test void httpRequiresCustomerCsrfAndRejectsSpoofing()throws Exception {mvc.perform(get("/api/customer/orders")).andExpect(status().isUnauthorized());var issued=customers.register("web-"+UUID.randomUUID().toString().substring(0,30),"合成",UUID.randomUUID().toString());var cookie=new Cookie("TICKET_CUSTOMER_SESSION",issued.token());var f=fixture(2,2);mvc.perform(post("/api/customer/orders").cookie(cookie).contentType("application/json").content(json.writeValueAsString(place(f,1)))).andExpect(status().isForbidden());var csrf=mvc.perform(get("/api/customer/auth/csrf")).andReturn();var token=json.readTree(csrf.getResponse().getContentAsString());String body=json.writeValueAsString(place(f,1));body=body.substring(0,body.length()-1)+",\"customerId\":\"spoof\"}";mvc.perform(post("/api/customer/orders").cookie(cookie,csrf.getResponse().getCookie("TICKET_CUSTOMER_CSRF")).header(token.get("headerName").asText(),token.get("token").asText()).contentType("application/json").content(body)).andExpect(status().isBadRequest());}
}
